def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = [v for row in grid for v in row if v]
    period = max(colors)
    offsets = []
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v and r > c:
                offsets.append((v - 1 - c) % period)
    offset = max(set(offsets), key=offsets.count)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                base = (c + offset) % period + 1
                out[r][c] = base if r > c else (base - 2) % period + 1
    return out
